"""Unit and Contract tests for the Python IoT Device Fleet Simulator."""

from __future__ import annotations

import random
import unittest
from datetime import datetime, timezone

from simulator.device_simulator import (
    DEFAULT_FLEET,
    build_telemetry_payload,
    load_contract_schema,
    run_fleet_simulation,
    validate_payload_against_contract,
)


def test_all_simulated_fleet_payloads_match_api_contract() -> None:
    """Every payload generated by the Python simulator must satisfy the shared JSON Schema contract."""
    summary = run_fleet_simulation(rounds=4, seed=42)

    assert summary.total_devices == 5
    assert summary.rounds == 4
    # 5 devices in round 1 + 4 active devices in rounds 2..4 (1 silent device) = 17 messages
    assert summary.messages_sent == 17
    assert summary.healthy_messages == 16
    assert summary.anomalous_messages == 1
    assert summary.silent_devices == ["iot-no-osl-003"]
    assert summary.contract_violations == 0

    for frame in summary.frames:
        assert frame["contractValid"] is True
        errors = validate_payload_against_contract(frame["payload"])
        assert errors == []


def test_out_of_range_injection_produces_threshold_breaching_metrics() -> None:
    """Out-of-range injection must remain schema-valid while breaching operational alert bounds."""
    rng = random.Random(99)
    sample_time = datetime(2026, 11, 2, 18, 0, 0, tzinfo=timezone.utc)
    payload = build_telemetry_payload(
        profile=DEFAULT_FLEET[0],
        sequence_number=5,
        sample_time=sample_time,
        rng=rng,
        inject_out_of_range=True,
    )

    assert validate_payload_against_contract(payload) == []
    assert payload["metrics"]["temperatureC"] > 45.0
    assert payload["metrics"]["batteryPct"] < 15.0
    assert payload["metrics"]["vibrationG"] > 4.0


def test_contract_validator_rejects_malformed_requests() -> None:
    """Verify the Python contract validator catches schema violations before or during testing."""
    schema = load_contract_schema()
    rng = random.Random(1)
    valid = build_telemetry_payload(
        profile=DEFAULT_FLEET[0],
        sequence_number=1,
        sample_time=datetime(2026, 11, 2, 18, 0, 0, tzinfo=timezone.utc),
        rng=rng,
    )
    assert validate_payload_against_contract(valid, schema) == []

    # 1. Missing required field and unknown property
    bad_payload = dict(valid)
    del bad_payload["firmwareVersion"]
    bad_payload["rogueField"] = 123
    errors = validate_payload_against_contract(bad_payload, schema)
    assert any("firmwareVersion" in e for e in errors)
    assert any("rogueField" in e for e in errors)

    # 2. Invalid RAT and out-of-bounds battery
    bad_nested = dict(valid)
    bad_nested["network"] = {"rat": "3G-UMTS", "rssiDbm": -75, "cellId": "SE-GBG-01"}
    bad_nested["metrics"] = {"temperatureC": 20.0, "humidityPct": 50.0, "batteryPct": 145.0}
    nested_errors = validate_payload_against_contract(bad_nested, schema)
    assert any("network.rat" in e for e in nested_errors)
    assert any("metrics.batteryPct" in e for e in nested_errors)


class SimulatorContractAndUnitTestSuite(unittest.TestCase):
    def test_fleet_payloads_match_contract(self) -> None:
        test_all_simulated_fleet_payloads_match_api_contract()

    def test_out_of_range_injection(self) -> None:
        test_out_of_range_injection_produces_threshold_breaching_metrics()

    def test_malformed_request_rejection(self) -> None:
        test_contract_validator_rejects_malformed_requests()


if __name__ == "__main__":
    unittest.main()
